import { chromium } from 'playwright'

const BASE = 'http://127.0.0.1:8093/wechatapph5/'
const URL = BASE + '#/pages-survey/index'

// 构造一道选项很多的题，强制答案区溢出以验证可滚动
const manyOptions = Array.from({ length: 18 }, (_, i) => `选项内容${i + 1}`)

const questionnaireResp = {
  MtplQuestionnaireModel: {
    description: '尊敬的园区各小区居民：您好！为了在苏州工业园区物业服务企业规范化考评中全面了解广大业主（使用人）对物业管理服务的需求，提高物业服务的认知度和满意度，根据《苏州工业园区商品住宅物业服务规范化考评办法》，请您如实填写下表。谢谢！苏州工业园区物业服务考评领导小组 2026年11月03日',
    totalCount: 1046,
    joinedCount: 0,
    examsList: [
      { no: '1', type: 0, topic: '您对本小区物业管理服务的期望如何？', options: manyOptions, required: 1, nochoisenum: 1 },
    ]
  }
}

const rateResp = { rate: 0, totalHouse: 1046, replyHouse: 0 }

async function main() {
  const browser = await chromium.launch()
  const context = await browser.newContext({
    viewport: { width: 393, height: 851 }, // 小米类 Android 视口
    isMobile: true,
    hasTouch: true,
    deviceScaleFactor: 3,
    userAgent: 'Mozilla/5.0 (Linux; Android 13; MI 13) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Mobile Safari/537.36'
  })
  const page = await context.newPage()

  await page.route('**/api/**', async (route) => {
    const url = route.request().url()
    let body = '{}'
    if (url.includes('SmQuestionnaireGoHandleApp')) body = JSON.stringify(questionnaireResp)
    else if (url.includes('SmQuestionnaireReplyRate')) body = JSON.stringify(rateResp)
    else if (url.includes('uploadQuestionnaireReply')) body = JSON.stringify({ code: 0 })
    await route.fulfill({ status: 200, contentType: 'application/json', body })
  })

  const errors = []
  page.on('pageerror', (e) => errors.push(String(e)))

  await page.goto(URL, { waitUntil: 'networkidle', timeout: 30000 })
  // 等待题目渲染
  await page.waitForSelector('.survey-page-answer-scrollable', { timeout: 15000 })
  await page.waitForTimeout(800)

  const info = await page.evaluate(() => {
    const el = document.querySelector('.survey-page-answer-scrollable')
    const pageEl = document.querySelector('.survey-page')
    const opts = document.querySelectorAll('.survey-page-options *')
    return {
      scrollClass: !!el,
      pageH: pageEl ? pageEl.getBoundingClientRect().height : null,
      viewportH: window.innerHeight,
      scrollClientH: el ? el.clientHeight : null,
      scrollH: el ? el.scrollHeight : null,
      optionCount: document.querySelectorAll('.survey-page-options div').length,
      overflowY: el ? getComputedStyle(el).overflowY : null,
    }
  })

  // 尝试滚动并测量 scrollTop 变化
  let scrollBefore = 0, scrollAfter = 0, scrollable = false
  if (info.scrollClientH && info.scrollH) {
    scrollable = info.scrollH > info.scrollClientH + 2
    const res = await page.evaluate(async () => {
      const el = document.querySelector('.survey-page-answer-scrollable')
      // uni-app 的 scroll-view 内部滚动容器
      const inner = el.querySelector('*') || el
      const target = (el.scrollHeight > el.clientHeight) ? el : inner
      const before = target.scrollTop
      el.scrollTop = 300
      if (el.scrollTop === before && target !== el) target.scrollTop = 300
      await new Promise(r => setTimeout(r, 300))
      return { before, afterEl: el.scrollTop, afterInner: target.scrollTop }
    })
    scrollBefore = res.before
    scrollAfter = Math.max(res.afterEl, res.afterInner)
  }

  console.log('=== RESULT ===')
  console.log(JSON.stringify({ ...info, scrollable, scrollBefore, scrollAfter, errors: errors.slice(0, 5) }, null, 2))

  await page.screenshot({ path: 'verify-survey-scroll.png', fullPage: false })
  await browser.close()

  const ok = info.scrollClass && info.pageH && Math.abs(info.pageH - info.viewportH) < 5 &&
    info.overflowY === 'auto' && scrollable && (scrollAfter - scrollBefore) > 50
  console.log(ok ? 'VERIFY_PASS' : 'VERIFY_FAIL')
  process.exit(ok ? 0 : 1)
}

main().catch((e) => { console.error(e); process.exit(2) })

